package dev.zomboid.lriso;import net.minecraft.client.Minecraft;import com.cleannrooster.dungeons_iso.mod.Mod;import org.lwjgl.glfw.GLFW;import me.xjqsh.lrtactical.client.input.AttackKeys;public class Checks {static int n;static void check(boolean b){n++;if(!b)throw new AssertionError(n);}public static class Hit {public net.minecraft.world.phys.Vec3 getLocation(){return new net.minecraft.world.phys.Vec3(3,0,0);}public String getType(){return "BLOCK";}}public static void main(String[] args){GLFW.pressed=true;check(Input.held(false));GLFW.pressed=false;check(!Input.held(false));check(Input.held(true));GLFW.pressed=true;Minecraft.M.screen=new Object();check(!Input.held(false));Minecraft.M.screen=null;Mod.enabled=false;check(!Input.held(false));Mod.enabled=true;Minecraft.M.active=false;check(!Input.held(false));Minecraft.M.active=true;AttackKeys.NORMAL_ATTACK.modifier="CTRL";check(!Input.held(false));AttackKeys.NORMAL_ATTACK.modifier="NONE";Mod.crosshairTarget=new Hit();var vector=(net.minecraft.world.phys.Vec3)Input.look(Minecraft.M.player);check(Math.abs(vector.x-1)<.001&&Math.abs(vector.y)<.001&&Math.abs(Minecraft.M.player.yaw+90)<.001);System.out.println("Passed "+n+" isometric input and direction checks (API doubles)");}}
